<script lang="ts">
  import BellIcon from "@lucide/svelte/icons/bell";
  import CheckIcon from "@lucide/svelte/icons/check";
  import FileTextIcon from "@lucide/svelte/icons/file-text";
  import MessageCircleIcon from "@lucide/svelte/icons/message-circle";
  import PencilIcon from "@lucide/svelte/icons/pencil";
  import PinIcon from "@lucide/svelte/icons/pin";
  import RocketIcon from "@lucide/svelte/icons/rocket";
  import SparklesIcon from "@lucide/svelte/icons/sparkles";
  import TagIcon from "@lucide/svelte/icons/tag";
  import ZapIcon from "@lucide/svelte/icons/zap";
  import { Mira } from "@lapismd/mira";
  import "@lapismd/mira/styles.css";
  import "@lapismd/mira/themes/obsidian.css";
  import { untrack } from "svelte";
  import { parseRoleDocument, patchRoleDocument } from "./roles/role-document";
  import { ROLE_STATUSES, type RolePatch, type RolePrepStage } from "./roles/types";

  let { filePath, content, onContentChange, onOpenCv, onTailorCv, onDelete }: {filePath:string;content:string;onContentChange?:(content:string)=>void|Promise<void>;onOpenCv?:(path:string)=>void|Promise<void>;onTailorCv?:(sourcePath:string)=>void|Promise<void>;onDelete?:()=>void|Promise<void>}=$props();
  let source=$state(untrack(()=>content));let activeTab=$state<"comments"|"stages"|"role"|"description"|"source">("role");let descriptionMode=$state<"source"|"preview">("preview");let stageName=$state("");let commentAuthor=$state("");let commentBody=$state("");let saveError=$state<string|null>(null);let expandedDescription=$state(false);
  const document=$derived(parseRoleDocument(filePath,source));
  const detailDisplayNumber=$derived(document.role ? ROLE_STATUSES.indexOf(document.role.status)*100+Math.max(1,Math.round(document.role.sortOrder/1000)) : 1);
  function uid(){return globalThis.crypto?.randomUUID?.()??Math.random().toString(36).slice(2)}
  function setSource(next:string){source=next;saveError=null;void Promise.resolve(onContentChange?.(next)).catch((error)=>saveError=error instanceof Error?error.message:String(error))}
  function commit(patch:RolePatch,body?:string){try{setSource(patchRoleDocument(filePath,source,patch,body))}catch(error){saveError=error instanceof Error?error.message:String(error)}}
  function addStage(){const role=document.role;const name=stageName.trim();if(!role||!name)return;const stage:RolePrepStage={id:uid(),type:"interview",name,status:"planned"};commit({prep:{...role.prep,stages:[...role.prep.stages,stage],updatedAt:new Date().toISOString()}});stageName=""}
  function addComment(){const role=document.role;const body=commentBody.trim();if(!role||!body)return;commit({prep:{...role.prep,comments:{...role.prep.comments,items:[...role.prep.comments.items,{id:uid(),author:commentAuthor.trim()||"You",body,createdAt:new Date().toISOString(),reactions:[]}]},updatedAt:new Date().toISOString()}});commentBody=""}
  function addReaction(emoji:string){const role=document.role;if(!role)return;commit({reactions:[...role.reactions,{id:uid(),emoji,author:"You",createdAt:new Date().toISOString()}]})}
  function compactDate(value:string|undefined){if(!value)return "—";const date=new Date(value);return Number.isNaN(date.valueOf())?value:date.toLocaleDateString(undefined,{day:"numeric",month:"short"})}
  function initials(value:string){return value.split(/\s+/).filter(Boolean).slice(0,2).map((part)=>part[0]?.toUpperCase()).join("")}
  async function confirmDelete(){if(!globalThis.confirm?.(`Delete ${document.role?.title??"this role"}?`))return;await onDelete?.()}
</script>

<div class="application-detail-screen" data-ui-component="role-workspace" data-kanban-theme="light">
  {#if document.diagnostics.length||saveError}<div class="detail-alert" role="alert"><strong>{saveError?"Role not saved":"Role source needs attention"}</strong> {saveError??document.diagnostics.map((item)=>item.message).join(" ")}</div>{/if}
  {#if !document.role}
    <section class="raw-role-source" aria-label="Raw role source"><Mira value={source} mode="source" toolbar={false} theme="obsidian" colorMode="inherit" blockControls={false} onChange={setSource}/></section>
  {:else}
    {@const role=document.role}
    <div class="detail-page">
      <header class="detail-header">
        <button type="button" class="detail-back" onclick={()=>history.back()}>Back</button>
        <div class="detail-brand" aria-label="CV Studio Applications"><span class="detail-logo" aria-hidden="true"><span></span><span></span><span></span><span></span></span><strong>CV Studio</strong><kbd>J</kbd></div>
      </header>
      <section class="detail-perma" aria-label={`Application ${detailDisplayNumber} detail`} style="--card-color:#0891b2">
        <div class="detail-actions detail-actions-left">
          <button type="button" class="detail-action-btn" class:active-detail-action={activeTab!=="role"} aria-label="Show application details" onclick={()=>activeTab="description"}><FileTextIcon /></button>
          <button type="button" class="detail-action-btn" class:active-detail-action={activeTab==="role"} aria-label="Edit properties" onclick={()=>activeTab="role"}><PencilIcon /></button>
        </div>
        <div class="detail-card-bg">
          <article class="detail-main-card">
            <header class="detail-card-header">
              <div class="card-board detail-board-label"><span>No. {detailDisplayNumber}</span><span>{role.company}</span></div>
              {#each role.tags.slice(0,3) as tag}<span class="detail-tag"><TagIcon />{tag}</span>{/each}
            </header>
            <div class="detail-card-body">
              <div class="detail-card-content">
                <div class="detail-copy">
                  <h1 class="detail-title">{role.title}</h1>
                  <p class="detail-subtitle">{[role.location,role.salary,role.source].filter(Boolean).join(" - ")}</p>
                  <button type="button" class:expanded={expandedDescription} class="detail-note-preview" onclick={()=>expandedDescription=!expandedDescription}><span>{role.description.replace(/^#+\s+/gm,"").trim()||"Add the role description in Markdown."}</span><em>{expandedDescription?"Show less":"Show more"}</em></button>
                </div>
                <div class="detail-steps">
                  <div class="linked-cv-row"><span class="link-label">Linked CV</span>{#if role.cvFile}<button type="button" class="linked-cv-open standalone" aria-label="Open linked CV" onclick={()=>onOpenCv?.(role.cvFile!)}>Open {role.cvFile.split("/").at(-1)?.replace(/\.cv\.ya?ml$/,"")}</button>{:else}<button type="button" class="linked-cv-open standalone" onclick={()=>activeTab="role"}>Link a CV...</button>{/if}</div>
                  <div class="linked-cv-row"><span class="link-label">Tailored CV</span><div class="tailored-cv-actions">{#if role.tailoredCvFile}<button type="button" onclick={()=>onOpenCv?.(role.tailoredCvFile!)}><FileTextIcon />Open tailored CV</button>{:else if role.cvFile}<button type="button" onclick={()=>onTailorCv?.(role.cvFile!)}><SparklesIcon />Create tailored CV</button>{/if}</div></div>
                </div>
              </div>
              <nav class="detail-stages" aria-label="Move application to stage">{#each ROLE_STATUSES as status}<button type="button" class:current-stage={status===role.status} disabled={status===role.status} onclick={()=>commit({status})}>{status}</button>{/each}</nav>
              {#if role.followUpAt}<button type="button" class="detail-stamp" onclick={()=>activeTab="role"}><span>Follow Up</span><strong>{compactDate(role.followUpAt)}</strong></button>{/if}
            </div>
            <footer class="detail-card-footer">
              <div class="detail-meta"><span class="card-avatar">{initials(role.contacts[0]??role.company)}</span><span>Added <strong>{compactDate(role.createdAt)}</strong></span><span>Updated <strong>{compactDate(role.updatedAt)}</strong></span><span>Source <strong>{role.source??"Tracked"}</strong></span><span>{role.contacts.join(" / ")||"No contact"}</span></div>
              <div class="detail-counts"><span><ZapIcon />{role.reactions.length}</span><span><MessageCircleIcon />{role.prep.comments.items.length}</span><button type="button" class="add-reaction-button card-add-reaction" aria-label="Add reaction to application" onclick={()=>addReaction("🚀")}><RocketIcon /></button></div>
            </footer>
          </article>
        </div>
        <div class="detail-actions detail-actions-right"><button type="button" class="detail-action-btn detail-dark" aria-label="Watch application"><BellIcon /></button><button type="button" class="detail-action-btn detail-dark" aria-label="Pin this application" onclick={()=>commit({pinned:!role.pinned})}><PinIcon /></button></div>
        <div class="detail-notch"><button type="button" class="detail-primary" disabled={role.status==="offer"} onclick={()=>commit({status:"offer"})}>Mark as Offer</button></div>
      </section>

      <section class="detail-lower" aria-label="Application detail panel">
        <div class="detail-tabs" role="tablist" aria-label="Application detail tabs">
          <button role="tab" aria-selected={activeTab==="comments"} class:active={activeTab==="comments"} onclick={()=>activeTab="comments"}>Comments</button>
          <button role="tab" aria-selected={activeTab==="stages"} class:active={activeTab==="stages"} onclick={()=>activeTab="stages"}>Stages</button>
          <button role="tab" aria-selected={activeTab==="role"} class:active={activeTab==="role"} onclick={()=>activeTab="role"}>Role</button>
          <button role="tab" aria-selected={activeTab==="description"} class:active={activeTab==="description"} onclick={()=>activeTab="description"}>Description</button>
          <button role="tab" aria-selected={activeTab==="source"} class:active={activeTab==="source"} onclick={()=>activeTab="source"}>Source</button>
        </div>
        {#if activeTab==="role"}
          <div class="role-property-list">
            <label><span>Id</span><input value={role.id} readonly /></label><label><span>Company</span><input value={role.company} onchange={(event)=>commit({company:event.currentTarget.value})}/></label><label><span>Title</span><input value={role.title} onchange={(event)=>commit({title:event.currentTarget.value})}/></label>
            <label><span>Status</span><select value={role.status} onchange={(event)=>commit({status:event.currentTarget.value as typeof role.status})}>{#each ROLE_STATUSES as status}<option value={status}>{status}</option>{/each}</select></label><label><span>Location</span><input value={role.location??""} onchange={(event)=>commit({location:event.currentTarget.value||undefined})}/></label><label><span>Salary</span><div class="salary-grid"><input value={role.salaryCurrency??""} placeholder="Currency" onchange={(event)=>commit({salaryCurrency:event.currentTarget.value||undefined})}/><input value={role.salary??""} placeholder="Salary label" onchange={(event)=>commit({salary:event.currentTarget.value||undefined})}/></div></label><label><span>Tags</span><input value={role.tags.join(", ")} onchange={(event)=>commit({tags:event.currentTarget.value.split(",").map((tag)=>tag.trim()).filter(Boolean)})}/></label><label><span>Contacts</span><input value={role.contacts.join(", ")} onchange={(event)=>commit({contacts:event.currentTarget.value.split(",").map((item)=>item.trim()).filter(Boolean)})}/></label><label><span>Follow up</span><input type="date" value={role.followUpAt?.slice(0,10)??""} onchange={(event)=>commit({followUpAt:event.currentTarget.value||undefined})}/></label><label><span>Linked CV</span><input value={role.cvFile??""} onchange={(event)=>commit({cvFile:event.currentTarget.value||undefined})}/></label>
          </div>
        {:else if activeTab==="stages"}
          <div class="stages-panel"><header><span>Stage preview</span><h2>{role.title} at {role.company}</h2><p>{role.prep.stages.length} {role.prep.stages.length===1?"stage":"stages"}</p></header>{#each role.prep.stages as stage,index (stage.id)}<article class="stage-card"><span>{String(index+1).padStart(2,"0")}</span><div><small>{stage.type}</small><h3>{stage.name}</h3>{#if stage.quickBrief}<p>{stage.quickBrief}</p>{/if}</div><em>{stage.status??"planned"}</em></article>{/each}<div class="panel-composer"><input aria-label="Interview or preparation stage" placeholder="Add a stage..." bind:value={stageName} onkeydown={(event)=>event.key==="Enter"&&addStage()}/><button type="button" onclick={addStage}>Add stage</button></div></div>
        {:else if activeTab==="comments"}
          <div class="comments-panel">{#each role.prep.comments.items as comment (comment.id)}<article><span class="comment-avatar">{initials(comment.author)}</span><div><header><strong>{comment.author}</strong><time datetime={comment.createdAt}>{new Date(comment.createdAt).toLocaleString()}</time></header><p>{comment.body}</p></div><button type="button">Edit</button></article>{/each}<div class="comment-composer"><input aria-label="Comment author" placeholder="Author" bind:value={commentAuthor}/><textarea aria-label="Comment" placeholder="Add a comment" bind:value={commentBody}></textarea><button type="button" onclick={addComment}>Add comment</button></div></div>
        {:else if activeTab==="description"}
          <div class="markdown-panel"><div class="markdown-controls"><button type="button" class:active={descriptionMode==="preview"} onclick={()=>descriptionMode="preview"}><FileTextIcon />Preview</button><button type="button" class:active={descriptionMode==="source"} onclick={()=>descriptionMode="source"}><PencilIcon />Edit</button></div><Mira value={role.description} mode={descriptionMode} sourcePath={filePath} toolbar theme="obsidian" colorMode="inherit" blockControls onChange={(body)=>commit({},body)}/></div>
        {:else}<div class="raw-role-source" aria-label="Raw role source"><Mira value={source} mode="source" sourcePath={filePath} toolbar={false} theme="obsidian" colorMode="inherit" blockControls={false} onChange={setSource}/></div>{/if}
      </section>
      <section class="delete-role"><button type="button" onclick={confirmDelete}>Delete this card</button></section>
    </div>
  {/if}
</div>

<style>
  .detail-alert{position:sticky;top:0;z-index:80;border-bottom:1px solid #fecaca;background:#fff1f2;color:#9f1239;padding:.65rem 1rem}
  .detail-lower{margin:0 3rem}.detail-tabs{display:flex;align-items:end;border-bottom:1px solid #e5e7eb}.detail-tabs button{height:3rem;border:0;border-bottom:2px solid transparent;background:transparent;color:#4b455f;font-weight:950;padding:0 1rem;cursor:pointer}.detail-tabs button.active{border:1px solid #8b80a0;border-bottom-color:white;background:white;color:#151229}.role-property-list{display:grid}.role-property-list label{display:grid;grid-template-columns:7rem minmax(0,1fr);align-items:center;border-bottom:1px solid #e5e7eb;padding:.55rem 0}.role-property-list label>span{color:#777188;font-size:.75rem;font-weight:800}.role-property-list input,.role-property-list select{width:100%;border:0;background:transparent;color:#151229;font:inherit;padding:.35rem}.role-property-list input:focus,.role-property-list select:focus{outline:1px solid #b7dbe4;background:#eef9fb}.salary-grid{display:grid;grid-template-columns:1fr 2fr;gap:.5rem}.salary-grid input{border:1px solid #d9dde4!important}.stages-panel{display:grid;gap:1.5rem;padding:1rem 0}.stages-panel>header,.stage-card{border:1px solid #e5e7eb;border-radius:.8rem;background:white;box-shadow:0 12px 28px rgb(15 23 42/.06);padding:1.3rem}.stages-panel>header span,.stage-card small{color:#6b647b;font-size:.68rem;font-weight:950;text-transform:uppercase}.stages-panel h2{margin:.2rem 0;font-size:1.7rem}.stage-card{display:grid;grid-template-columns:auto 1fr auto;gap:1rem;align-items:start}.stage-card>span{display:grid;width:2.5rem;height:2.5rem;place-items:center;border-radius:999px;background:#e7f5f8;color:#268ca7;font-weight:950}.stage-card h3{margin:.25rem 0}.stage-card em{border-radius:999px;background:#f5f5f7;font-size:.65rem;font-style:normal;font-weight:900;padding:.35rem .6rem;text-transform:uppercase}.panel-composer,.comment-composer{display:grid;grid-template-columns:1fr auto;gap:.5rem}.panel-composer input,.comment-composer input,.comment-composer textarea{border:1px solid #d9dde4;border-radius:.4rem;padding:.65rem}.panel-composer button,.comment-composer button{border:1px solid #0891b2;border-radius:999px;background:white;color:#0891b2;font-weight:900;padding:0 .8rem}.comments-panel{display:grid}.comments-panel article{display:grid;grid-template-columns:auto 1fr auto;gap:.75rem;border-bottom:1px solid #e5e7eb;padding:1.25rem 0}.comment-avatar{display:grid;width:2rem;height:2rem;place-items:center;border-radius:999px;background:#2594ad;color:white;font-size:.7rem;font-weight:950}.comments-panel header{display:grid}.comments-panel time{font-size:.68rem;font-weight:800}.comments-panel article>button{align-self:start;border:1px solid #e5e7eb;border-radius:999px;background:white;font-size:.68rem;font-weight:900;padding:.35rem .65rem}.comment-composer{grid-template-columns:1fr auto;margin-top:1rem}.comment-composer textarea{grid-column:1/-1;min-height:5rem}.markdown-panel,.raw-role-source{display:flex;min-height:28rem;flex-direction:column}.markdown-controls{display:flex;justify-content:end;gap:.4rem;padding:.6rem}.markdown-controls button{display:inline-flex;align-items:center;gap:.35rem;border:1px solid #e5e7eb;border-radius:999px;background:white;padding:.45rem .7rem}.markdown-controls button.active{background:#101a35;color:white}.markdown-controls :global(svg){width:.9rem}.markdown-panel :global(.mira),.raw-role-source :global(.mira){min-height:26rem;flex:1;border:0}.delete-role{margin:2rem 3rem 0;border-top:1px solid #e5e7eb;padding-top:1rem}.delete-role button{border:1px solid #ef4444;border-radius:999px;background:white;color:#b91c1c;padding:.55rem .8rem}
  @media(max-width:760px){.detail-tabs{overflow:auto}.detail-tabs button{padding:0 .65rem}.role-property-list label{grid-template-columns:5rem 1fr}}

  /* Ported from CV Studio ApplicationDetailPanel.css and
     ApplicationDetailPanel.actions.css. Lapis owns only the surrounding leaf. */
  .application-detail-screen{--kanban-background:oklch(100% 0 0);--kanban-foreground:oklch(15% .05 295);--kanban-card:oklch(100% 0 0);--kanban-card-foreground:oklch(15% .05 295);--kanban-muted:oklch(50% .05 295);--kanban-muted-surface:oklch(96.5% .015 295);--kanban-border:oklch(92.5% .02 295);--kanban-shadow:rgb(15 23 42/.1);--card-content:color-mix(in srgb,var(--card-color,#0891b2) 46%,var(--kanban-card-foreground));position:relative;display:flex;min-height:100%;overflow-x:hidden;background:var(--kanban-background);color:var(--card-content)}
  .detail-page{width:100%;min-height:100dvh;margin:0;padding:0 0 4rem;background:var(--kanban-background);--detail-action-size:3rem}
