  .detail-brand{display:flex;align-items:center;gap:.45rem;color:var(--kanban-foreground);font-size:1.35rem;font-weight:950}.detail-brand kbd{border:1px solid var(--kanban-border);border-radius:.25rem;background:var(--kanban-muted-surface);color:var(--kanban-muted);font-size:.7em;font-weight:900;line-height:1;padding:.18rem .32rem;text-transform:uppercase}
  .detail-logo{display:inline-flex;width:1.65rem;height:1.65rem;align-items:center;justify-content:center;gap:.12rem;border-radius:.35rem;background:var(--kanban-muted-surface);box-shadow:inset 0 0 0 1px var(--kanban-border)}.detail-logo span{width:.18rem;height:1.05rem;border-radius:999px}.detail-logo span:nth-child(1){background:#2563eb}.detail-logo span:nth-child(2){background:#f59e0b}.detail-logo span:nth-child(3){background:#ef4444}.detail-logo span:nth-child(4){background:#14b8a6}
  .detail-perma{--detail-action-size:3rem;display:grid;width:min(82rem,calc(100% - 3rem));grid-template-areas:"left card right" "left notch right";grid-template-columns:var(--detail-action-size) minmax(0,68rem) var(--detail-action-size);gap:0 .8rem;margin-inline:auto}
  .detail-card-bg{grid-area:card;border-radius:.18rem;background:color-mix(in srgb,var(--card-color) 34%,var(--kanban-card));padding:clamp(1.6rem,3vw,3rem)}
  .detail-main-card{position:relative;display:flex;min-height:min(52dvh,31rem);flex-direction:column;overflow:hidden;border-radius:.28rem;background:color-mix(in srgb,var(--card-color) 4%,var(--kanban-card));box-shadow:0 10px 24px var(--kanban-shadow),inset 0 0 0 1px color-mix(in srgb,var(--card-color) 20%,transparent)}
  .detail-card-header{display:flex;align-items:flex-start;gap:.75rem;padding:.75rem 1.2rem 0 0}.card-board{display:inline-flex;max-width:min(70%,36rem);align-items:center;gap:.5rem;border-radius:0 0 .2rem 0;background:var(--card-color);color:white;font-size:1rem;font-weight:950;line-height:1;padding:.55rem .8rem .55rem 1rem}.card-board span:last-child{min-width:0;overflow:hidden;border-left:1px solid rgb(255 255 255/.35);padding-left:.5rem;text-overflow:ellipsis;text-transform:uppercase;white-space:nowrap}
  .detail-tag{display:inline-flex;height:2rem;align-items:center;gap:.3rem;margin-top:.25rem;border:1px solid color-mix(in srgb,var(--card-color) 25%,transparent);border-radius:999px;color:var(--card-color);font-size:.75rem;font-weight:900;padding:0 .6rem;text-transform:uppercase}.detail-tag :global(svg),.detail-counts :global(svg),.detail-action-btn :global(svg),.detail-steps :global(svg),.add-reaction-button :global(svg){width:1rem;height:1rem}
  .detail-card-body{position:relative;display:grid;flex:1;grid-template-columns:minmax(0,1fr) 10rem;gap:2rem;padding:1.1rem 1.5rem 1rem}.detail-card-content{display:flex;min-width:0;flex-direction:column;justify-content:space-between}.detail-copy{display:grid;align-content:start;gap:.85rem}
  .detail-title{max-width:42rem;margin:0;color:var(--card-content);font-size:clamp(2rem,4vw,3.1rem);font-weight:950;letter-spacing:0;line-height:1.05;text-wrap:balance}.detail-subtitle{margin:.8rem 0 0;color:color-mix(in srgb,var(--card-color) 48%,var(--kanban-muted));font-size:1rem;font-weight:850;text-transform:uppercase}
  .detail-note-preview{display:grid;max-width:46rem;max-height:8.25rem;margin:1rem 0 0;overflow:hidden;border:0;background:transparent;color:color-mix(in srgb,var(--card-color) 52%,var(--kanban-card-foreground));cursor:text;font:inherit;font-size:1rem;line-height:1.65;padding:0;text-align:left;white-space:pre-line}.detail-note-preview.expanded{max-height:none}.detail-note-preview em{width:fit-content;margin-top:.45rem;border-radius:999px;background:color-mix(in srgb,var(--card-color) 8%,var(--kanban-card));color:var(--card-color);font-size:.72rem;font-style:normal;font-weight:950;padding:.45rem .7rem}
  .detail-steps{display:grid;align-content:end;gap:.8rem;color:var(--card-color);font-size:1.05rem;font-weight:800;margin-top:1.6rem}.linked-cv-row{display:grid;width:min(36rem,100%);min-width:0;gap:.35rem}.link-label{color:color-mix(in srgb,var(--card-color) 62%,var(--kanban-muted));font-size:.72rem;font-weight:950;text-transform:uppercase}
